import { ClassRecord, FetchedCourse, FetchResult, StoredCourseRow } from "./types";

/**
 * A course that has been discontinued upstream (it will never appear in a
 * fetch again) but is still referenced by a past-term class. Every test
 * fixture below includes this row in the store and none of them ever
 * include it in a fetch -- a correct reconciler must never remove it.
 */
export const discontinuedCourse: StoredCourseRow = {
  courseId: "19003",
  subject: "MUSIC",
  number: "32",
  title: "Introduction to Music Theory",
};

export const referencingClass: ClassRecord = {
  classId: "MUSIC-32-2018-FA-001",
  courseId: discontinuedCourse.courseId,
  term: "2018-Fall",
};

/** Builds a fetchCourses() implementation backed by a fixed, in-memory result. */
export function makeFetcher(
  courses: FetchedCourse[],
  failedPages: number[] = []
): () => Promise<FetchResult> {
  return async () => ({ courses, failedPages });
}
